package run.ikaros.finance; import jakarta.validation.Valid; import java.time.YearMonth; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}/budgets") public class BudgetController{private final BudgetService service;public BudgetController(BudgetService s){service=s;}@PutMapping public Mono<BudgetView> save(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateBudgetRequest r){return service.save(a,ledgerId,r);}@GetMapping public Flux<BudgetView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@RequestParam YearMonth month){return service.list(a,ledgerId,month);}}
